import { motion } from 'framer-motion';
import { characters } from '../../data/scriptData';

interface GuestSofaProps {
  guestId: string;
  isActive: boolean;
  position: 'left' | 'center' | 'right';
  suspicionScore?: number;
  isLiarsRevealed?: boolean;
}

export function GuestSofa({ guestId, isActive, position, suspicionScore = 0, isLiarsRevealed = false }: GuestSofaProps) {
  const guest = characters.find(c => c.id === guestId);
  if (!guest) return null;
  
  const isLiars = isLiarsRevealed && (guestId === 'guestA' || guestId === 'guestC');
  
  const positionStyles = {
    left: 'left-16',
    center: 'left-1/2 -translate-x-1/2',
    right: 'right-16',
  };
  
  return (
    <motion.div
      className={`absolute bottom-24 ${positionStyles[position]}`}
      initial={{ opacity: 0, y: 50 }}
      animate={{ 
        opacity: 1, 
        y: 0,
        scale: isActive ? 1.05 : 1,
      }}
      transition={{ duration: 0.5 }}
    >
      <div className="relative">
        <motion.div
          className={`w-28 h-36 rounded-2xl backdrop-blur-md border-2 transition-all duration-300 ${
            isLiars 
              ? 'bg-red-900/30 border-red-500/50' 
              : isActive 
                ? 'bg-slate-700/50 border-blue-400/50' 
                : 'bg-slate-800/40 border-slate-600/30'
          }`}
          animate={{
            boxShadow: isActive 
              ? '0 0 30px rgba(59, 130, 246, 0.5), inset 0 0 20px rgba(59, 130, 246, 0.1)'
              : isLiars
                ? '0 0 30px rgba(239, 68, 68, 0.5), inset 0 0 20px rgba(239, 68, 68, 0.1)'
                : '0 0 10px rgba(100, 116, 139, 0.2)',
          }}
        >
          <motion.div
            className={`absolute top-4 left-1/2 -translate-x-1/2 w-16 h-16 rounded-full flex items-center justify-center border-2 ${
              isLiars ? 'border-red-400' : 'border-blue-300/50'
            }`}
            style={{
              background: `linear-gradient(135deg, ${guest.color}66, ${guest.color}33)`,
            }}
            animate={{
              scale: isActive ? [1, 1.05, 1] : 1,
            }}
            transition={{
              duration: 1.5,
              repeat: isActive ? Infinity : 0,
              ease: 'easeInOut',
            }}
          >
            <span className="text-white font-bold text-xl">{guest.name[0]}</span>
          </motion.div>
          
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-center">
            <div className={`text-sm font-medium ${isLiars ? 'text-red-400' : 'text-white'}`}>
              {guest.name}
            </div>
            <div className="text-xs text-slate-400 mt-0.5">嘉宾{guestId.replace('guest', '')}</div>
          </div>
          
          {suspicionScore > 0 && (
            <motion.div
              className="absolute -top-2 left-1/2 -translate-x-1/2 px-3 py-1 rounded-full bg-red-600/80 backdrop-blur-sm border border-red-400/50"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: 'spring', stiffness: 500 }}
            >
              <span className="text-xs text-white font-bold">嫌疑值 {suspicionScore}</span>
            </motion.div>
          )}
          
          {isLiars && (
            <motion.div
              className="absolute -top-2 left-1/2 -translate-x-1/2 px-3 py-1 rounded-full bg-red-600/90 backdrop-blur-sm border-2 border-red-400"
              initial={{ scale: 0, rotate: -10 }}
              animate={{ scale: 1, rotate: 0 }}
              transition={{ type: 'spring', stiffness: 500 }}
            >
              <span className="text-xs text-white font-bold">说谎者</span>
            </motion.div>
          )}
        </motion.div>
        
        <motion.div
          className="absolute -bottom-2 left-2 right-2 h-2 rounded-full blur-md"
          style={{
            backgroundColor: isLiars ? 'rgba(239, 68, 68, 0.3)' : 'rgba(100, 116, 139, 0.2)',
          }}
          animate={{
            opacity: isActive ? [0.3, 0.6, 0.3] : 0.2,
          }}
          transition={{
            duration: 2,
            repeat: isActive ? Infinity : 0,
            ease: 'easeInOut',
          }}
        />
      </div>
    </motion.div>
  );
}
