import { motion } from 'framer-motion';
import { Character } from '../../data/scriptData';

interface SubtitleBarProps {
  character: Character | null;
  text: string;
  isPlaying: boolean;
  progress: number;
}

export function SubtitleBar({ character, text, isPlaying, progress }: SubtitleBarProps) {
  if (!character && !text) return null;

  const isAI = character?.id === 'ai';

  return (
    <motion.div
      className="absolute bottom-32 left-1/2 -translate-x-1/2 w-full max-w-4xl px-8"
      initial={{ opacity: 0, y: 50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <div className="relative">
        <div className="absolute -inset-1 bg-gradient-to-r from-blue-600/30 via-purple-600/30 to-blue-600/30 rounded-2xl blur-xl" />
        
        <div className="relative bg-slate-900/80 backdrop-blur-xl rounded-xl border border-blue-500/20 p-6">
          <div className="flex items-center gap-4 mb-3">
            {character && (
              <motion.div
                className="relative"
                animate={{
                  scale: isPlaying ? [1, 1.02, 1] : 1,
                }}
                transition={{
                  duration: 2,
                  repeat: Infinity,
                  ease: 'easeInOut',
                }}
              >
                <div
                  className={`w-12 h-12 rounded-full flex items-center justify-center border-2 ${
                    isAI ? 'border-cyan-400/60' : 'border-blue-400/40'
                  }`}
                  style={{
                    background: isAI 
                      ? 'linear-gradient(135deg, rgba(34, 211, 238, 0.3), rgba(99, 102, 241, 0.3))'
                      : character.color 
                        ? `linear-gradient(135deg, ${character.color}66, ${character.color}33)`
                        : 'linear-gradient(135deg, rgba(59, 130, 246, 0.3), rgba(139, 92, 246, 0.3))',
                  }}
                >
                  <span className={`text-lg font-bold ${isAI ? 'text-cyan-300' : 'text-white'}`}>
                    {isAI ? 'AI' : character.name[0]}
                  </span>
                </div>
                
                <motion.div
                  className={`absolute -inset-2 rounded-full blur-md ${
                    isAI ? 'bg-cyan-500/30' : character.color ? '' : 'bg-blue-500/30'
                  }`}
                  style={
                    !isAI && character.color
                      ? { backgroundColor: `${character.color}33` }
                      : undefined
                  }
                  animate={{
                    opacity: isPlaying ? [0.3, 0.6, 0.3] : 0.2,
                  }}
                  transition={{
                    duration: 2,
                    repeat: Infinity,
                    ease: 'easeInOut',
                  }}
                />
              </motion.div>
            )}
            
            <div className="flex-1">
              <div
                className={`text-sm font-medium ${
                  isAI ? 'text-cyan-400' : character?.color ? '' : 'text-blue-400'
                }`}
                style={
                  !isAI && character?.color
                    ? { color: character.color }
                    : undefined
                }
              >
                {isAI ? 'AI分析系统' : character?.name}
              </div>
              {character?.description && (
                <div className="text-xs text-slate-500">
                  {character.description}
                </div>
              )}
            </div>
          </div>
          
          <motion.div
            className={`text-xl leading-relaxed ${
              isAI ? 'text-cyan-200 font-mono' : 'text-white'
            }`}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.3 }}
          >
            {text.split('').map((char, index) => (
              <motion.span
                key={index}
                initial={{ opacity: 0, y: 5 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{
                  duration: 0.05,
                  delay: index * 0.02,
                }}
              >
                {char}
              </motion.span>
            ))}
          </motion.div>
          
          <div className="mt-4 h-1 bg-slate-700/50 rounded-full overflow-hidden">
            <motion.div
              className={`h-full rounded-full ${
                isAI ? 'bg-gradient-to-r from-cyan-500 to-blue-500' : 'bg-gradient-to-r from-blue-500 to-purple-500'
              }`}
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{
                duration: 0.1,
                ease: 'linear',
              }}
            />
          </div>
        </div>
      </div>
    </motion.div>
  );
}