import { useState, useEffect, useCallback, useRef } from 'react';
import { scenes, characters, analysisResults, trueLiars } from '../data/scriptData';

// 场景索引从数据派生，避免分镜增删后硬编码下标失效
const REVEAL_SCENE_INDEX = scenes.findIndex(s => s.title === '反转揭晓');
const ANALYSIS_SCENE_INDEX = scenes.findIndex(s => s.title === 'AI全面分析');

export interface PlayerState {
  currentSceneIndex: number;
  currentLineIndex: number;
  isPlaying: boolean;
  isPaused: boolean;
  isFinished: boolean;
  currentLineStartTime: number;
  currentActiveCharacter: string | null;
  isLiarsRevealed: boolean;
}

export function useScriptPlayer() {
  const [state, setState] = useState<PlayerState>({
    currentSceneIndex: 0,
    currentLineIndex: 0,
    isPlaying: false,
    isPaused: false,
    isFinished: false,
    currentLineStartTime: 0,
    currentActiveCharacter: null,
    isLiarsRevealed: false,
  });

  const timerRef = useRef<number | null>(null);

  const currentScene = scenes[state.currentSceneIndex];
  const currentLine = currentScene?.lines[state.currentLineIndex];
  const currentCharacter = currentLine 
    ? characters.find(c => c.id === currentLine.characterId) 
    : null;

  const startPlayback = useCallback(() => {
    setState(prev => ({
      ...prev,
      isPlaying: true,
      isPaused: false,
      currentLineStartTime: Date.now(),
    }));
  }, []);

  const pausePlayback = useCallback(() => {
    setState(prev => ({
      ...prev,
      isPlaying: false,
      isPaused: true,
    }));
  }, []);

  const resumePlayback = useCallback(() => {
    setState(prev => ({
      ...prev,
      isPlaying: true,
      isPaused: false,
      currentLineStartTime: Date.now(),
    }));
  }, []);

  const goToScene = useCallback((sceneIndex: number) => {
    setState({
      currentSceneIndex: Math.max(0, Math.min(sceneIndex, scenes.length - 1)),
      currentLineIndex: 0,
      isPlaying: false,
      isPaused: false,
      isFinished: false,
      currentLineStartTime: 0,
      currentActiveCharacter: null,
      isLiarsRevealed: sceneIndex >= REVEAL_SCENE_INDEX,
    });
  }, []);

  const goToNextScene = useCallback(() => {
    setState(prev => {
      const nextSceneIndex = prev.currentSceneIndex + 1;
      if (nextSceneIndex >= scenes.length) {
        return {
          ...prev,
          isPlaying: false,
          isFinished: true,
          isLiarsRevealed: true,
        };
      }
      return {
        ...prev,
        currentSceneIndex: nextSceneIndex,
        currentLineIndex: 0,
        currentLineStartTime: Date.now(),
        isLiarsRevealed: nextSceneIndex >= REVEAL_SCENE_INDEX,
      };
    });
  }, []);

  const goToNextLine = useCallback(() => {
    setState(prev => {
      const scene = scenes[prev.currentSceneIndex];
      if (!scene) return prev;

      const nextLineIndex = prev.currentLineIndex + 1;
      if (nextLineIndex >= scene.lines.length) {
        const nextSceneIndex = prev.currentSceneIndex + 1;
        if (nextSceneIndex >= scenes.length) {
          return {
            ...prev,
            isPlaying: false,
            isFinished: true,
            isLiarsRevealed: true,
          };
        }
        return {
          ...prev,
          currentSceneIndex: nextSceneIndex,
          currentLineIndex: 0,
          currentLineStartTime: Date.now(),
          isLiarsRevealed: nextSceneIndex >= REVEAL_SCENE_INDEX,
        };
      }

      return {
        ...prev,
        currentLineIndex: nextLineIndex,
        currentLineStartTime: Date.now(),
      };
    });
  }, []);

  useEffect(() => {
    if (!state.isPlaying || !currentLine) {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
      return;
    }

    const elapsed = Date.now() - state.currentLineStartTime;
    const remaining = currentLine.duration * 1000 - elapsed;

    if (remaining <= 0) {
      goToNextLine();
      return;
    }

    timerRef.current = window.setTimeout(() => {
      goToNextLine();
    }, remaining);

    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    };
  }, [state.isPlaying, state.currentLineStartTime, currentLine, goToNextLine]);

  useEffect(() => {
    setState(prev => ({
      ...prev,
      currentActiveCharacter: currentLine?.characterId || null,
    }));
  }, [currentLine?.characterId]);

  const getSuspicionScore = useCallback((guestId: string): number => {
    if (state.currentSceneIndex < ANALYSIS_SCENE_INDEX) return 0;
    const result = analysisResults.find(r => r.guestId === guestId);
    return result?.score || 0;
  }, [state.currentSceneIndex]);

  const getCurrentProgress = useCallback(() => {
    if (!currentLine || !state.isPlaying) return 0;
    const elapsed = Date.now() - state.currentLineStartTime;
    return Math.min(100, (elapsed / (currentLine.duration * 1000)) * 100);
  }, [currentLine, state.currentLineStartTime, state.isPlaying]);

  const getTotalProgress = useCallback(() => {
    let completedTime = 0;
    for (let i = 0; i < state.currentSceneIndex; i++) {
      completedTime += scenes[i].duration;
    }
    if (currentLine && state.isPlaying) {
      const elapsed = (Date.now() - state.currentLineStartTime) / 1000;
      completedTime += elapsed;
    } else if (currentLine && !state.isPlaying && state.currentLineIndex > 0) {
      for (let i = 0; i < state.currentLineIndex; i++) {
        completedTime += currentScene.lines[i].duration;
      }
    }

    const totalTime = scenes.reduce((sum, scene) => sum + scene.duration, 0);
    return Math.min(100, (completedTime / totalTime) * 100);
  }, [state.currentSceneIndex, state.currentLineIndex, state.isPlaying, state.currentLineStartTime, currentLine, currentScene]);

  return {
    state,
    currentScene,
    currentLine,
    currentCharacter,
    startPlayback,
    pausePlayback,
    resumePlayback,
    goToScene,
    goToNextScene,
    goToNextLine,
    getSuspicionScore,
    getCurrentProgress,
    getTotalProgress,
    isLiarsRevealed: state.currentSceneIndex >= REVEAL_SCENE_INDEX,
    trueLiars,
  };
}